message.content:
{
"css": ".day-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.day-tabs button {
  min-width: 64px;
  height: 32px;
  padding: 0 12px;
  border-radius: 16px;
  font-size: 14px;
  font-weight: 700;
  line-height: 32px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: none;
}

/* Selected State */
.day-tabs button[aria-pressed="true"] {
  background-color: #111;
  color: #fff;
  border: 1px solid transparent;
}

/* Unselected State */
.day-tabs button[aria-pressed="false"] {
  background-color: #fff;
  color: #111;
  border: 1px solid var(--border, #e8e8e8);
}"
}
